end

const SPLIT_OPTIONS = (i = "-i", input = "--input", n = "-n", number = "--number", p = "-p", prefix = "--prefix", a = "-a", algorithm = "--algorithm")
const SPLIT_ALIASES = ((:i, :input), (:n, :number), (:p, :prefix), (:a, :algorithm))
const SPLIT_REQUIRED = ((:i, :input), (:n, :number))

@doc raw"""
    BEDTools.Bindings.split(; options...)::Cmd

Split a Bed file.

The `bedtools split` command with `options`, checked against those that its help lists, to run with [`BEDTools.lines`](@ref) or any of Julia's process functions.
It needs `i` or `input` and `n` or `number`: `BEDTools.Bindings.split(i = …, n = …)`.
Its usage, in BEDTools 2.31.1, is `bedtools split [OPTIONS] -i <bed> -n number-of-files`.

An option of `true` is a flag, `false` and `nothing` leave it out, a vector gives it each element as an argument, and another value gives it that value.
An option with several spellings, such as a short and a long form, takes any one of them, and each emits its own.

Options:
- `i`, `input`: (file) BED input file (req'd).
- `n`, `number`: (int) Number of files to create (req'd).
- `p`, `prefix`: (string) Output BED file prefix.
- `a`, `algorithm`: (string) Algorithm used to split data. * size (default): uses a heuristic algorithm to group the items so all files contain the ~ same number of bases * simple : route records such that each split file has approximately equal records (like Unix split).

It also takes the general parameters of BEDTools, in [`BEDTools.Bindings.GENERAL_OPTIONS`](@ref), which come before the subcommand.
"""
function split(; options...)
    return build("split", SPLIT_OPTIONS, SPLIT_ALIASES, SPLIT_REQUIRED; options...)
end

const SUMMARY_OPTIONS = (i = "-i", g = "-g")
const SUMMARY_ALIASES = ()
const SUMMARY_REQUIRED = ((:i,), (:g,))

@doc raw"""
    BEDTools.Bindings.summary(; options...)::Cmd

Report summary statistics of the intervals in a file

The `bedtools summary` command with `options`, checked against those that its help lists, to run with [`BEDTools.lines`](@ref) or any of Julia's process functions.
It needs `i` and `g`: `BEDTools.Bindings.summary(i = …, g = …)`.
Its usage, in BEDTools 2.31.1, is `bedtools summary [OPTIONS] -i <bed/gff/vcf/bam> -g <genome>`.

An option of `true` is a flag, `false` and `nothing` leave it out, a vector gives it each element as an argument, and another value gives it that value.
An option with several spellings, such as a short and a long form, takes any one of them, and each emits its own.

Options:
- `i`: `<bed/gff/vcf/bam>`, from the usage line.
- `g`: `<genome>`, from the usage line.

It also takes the general parameters of BEDTools, in [`BEDTools.Bindings.GENERAL_OPTIONS`](@ref), which come before the subcommand.
"""
function summary(; options...)
    return build("summary", SUMMARY_OPTIONS, SUMMARY_ALIASES, SUMMARY_REQUIRED; options...)
end
